const source = process.argv.find(arg => arg.startsWith('--source-root='))?.slice('--source-root='.length);
if (source === '<candidate-backend>') {
  const { default: db } = await import('<candidate-backend>/src/lib/prisma.js');
  const originalRoles = db.jobRole.findMany, originalProfiles = db.costProfile.findMany;
  let pending;
  const packet = () => pending ??= db.$queryRaw`
    SELECT COALESCE((SELECT json_agg(json_build_object('id', r.id, 'name', r.name)) FROM "public"."JobRole" r), '[]'::json) AS roles,
      COALESCE((SELECT json_agg(json_build_object('key', p.key, 'jobRoleId', p."jobRoleId",
        'parameterSets', COALESCE((SELECT json_agg(json_build_object('version', s.version,
          'effectiveDate', s."effectiveDate"::text, 'createdAt', s."createdAt" AT TIME ZONE 'UTC', 'params', s.params))
          FROM "public"."CostParameterSet" s WHERE s."costProfileId" = p.id), '[]'::json)))
        FROM "public"."CostProfile" p), '[]'::json) AS profiles
  `.then(([row]) => row).finally(() => { pending = null; });
  db.jobRole.findMany = args => args?.select?.id && args?.select?.name && !args.where
    ? packet().then(row => row.roles) : originalRoles.call(db.jobRole, args);
  db.costProfile.findMany = args => args?.select?.parameterSets
    ? packet().then(row => row.profiles) : originalProfiles.call(db.costProfile, args);
}

scope-driver.script:
const source = process.argv.find(arg => arg.startsWith('--source-root='))?.slice('--source-root='.length);
if (source === '<candidate-backend>') {
  const {default:pg}=await import('<candidate-backend>/node_modules/pg/lib/index.js');
  const BasePool=pg.Pool;let pool;
  pg.Pool=class extends BasePool {constructor(...args){super(...args);pool??=this;}};
  const {default:db}=await import('<candidate-backend>/src/lib/prisma.js');
  const select='SELECT id, "fileName", "contentHash", source, "periodStart"::timestamp AT TIME ZONE \'UTC\' AS "periodStart", "periodEnd"::timestamp AT TIME ZONE \'UTC\' AS "periodEnd", "rowsRead", "collaboratorsTotal", "collaboratorsMatched", summary, status, "importedByUserId", "createdAt" AT TIME ZONE \'UTC\' AS "createdAt" FROM "public"."PontoImport"';
  db.pontoImport.findMany=()=>pool.query(select+' ORDER BY "createdAt" ASC').then(r=>r.rows);
  db.pontoImport.findUnique=({where})=>pool.query(select+' WHERE id = $1',[where.id]).then(r=>r.rows[0]??null);
}
